// Get current memory usage
size_t current_usage = cache_->TotalCharge();

// If we're already under target, do nothing
if (current_usage <= target_usage) {
    return;
}

// Lock the mutex to safely access cache state
MutexLock lock(&mutex_);

// Iterate through shards to find entries to evict
for (size_t i = 0; i < shard_; i++) {
    Shard* shard = &shard_[i];
    MutexLock l(&shard->mutex);

    // Calculate how much we need to evict from this shard
    size_t shard_usage = shard->lru_.ApproximateMemoryUsage();
    size_t shard_target = (target_usage * i) / shard_;
    size_t shard_evict = shard_usage - shard_target;

    if (shard_evict <= 0) continue;

    // Evict from LRU list until we reach target
    while (shard_evict > 0 && !shard->lru_.empty()) {
        LRUHandle* handle = shard->lru_.lru_.next;
        if (handle == &shard->lru_.lru_) break;  // Empty list

        // Calculate how much we can evict from this entry
        size_t evict_size = std::min(handle->charge, shard_evict);

        // Remove from cache
        shard->lru_.Remove(handle);

        // Call deleter if needed
        if (!handle->in_cache) {
            (*handle->deleter)(handle->key(), handle->value);
        }

        // Update eviction stats
        shard_evict -= evict_size;
    }
}

